//! The `--json` report (FR-191, "Outputs").

use ix_cli_kit::exit::Outcome;
use serde::Serialize;

use crate::error::{QuireFailure, SourceFailure};
use crate::gap::Gap;

/// Whether a document holds any gap.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Status {
    /// No gap.
    Complete,
    /// At least one gap.
    Incomplete,
}

/// How the regenerated bytes compare with the file on disk.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Comparison {
    /// The bytes are equal.
    Matches,
    /// The bytes differ, or the file is missing.
    Differs,
}

/// One document's entry.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct DocumentReport {
    /// The document id, for example `DOS-SRS`.
    pub id: String,
    /// The document kind, for example `srs`.
    pub kind: String,
    /// Where the file is, or would be written.
    pub path: String,
    /// `complete` or `incomplete`.
    pub status: Status,
    /// Present for `check` and `export` only.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub comparison: Option<Comparison>,
    /// The gaps, in the order the Markdown lists them.
    pub gaps: Vec<Gap>,
}

/// The whole report.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize)]
pub struct Report {
    /// One entry per selected document, in registry order.
    pub documents: Vec<DocumentReport>,
    /// Present on exit 3.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub source_failure: Option<SourceFailure>,
    /// Present on exit 4.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub quire: Option<QuireFailure>,
    /// Why export could not resolve the repository revision before checking
    /// committed document currency. Documents are still reported as `differs`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub export_currency_failure: Option<String>,
}

impl Report {
    /// The exit status of a run that produced documents: 0 when every
    /// document is complete and, where compared, matches; otherwise 1.
    #[must_use]
    pub fn outcome(&self) -> Outcome {
        let clean = self.documents.iter().all(|document| {
            document.status == Status::Complete && document.comparison != Some(Comparison::Differs)
        });
        if clean { Outcome::Ok } else { Outcome::Partial }
    }

    /// The ids of documents whose file is missing or stale.
    #[must_use]
    pub fn differing(&self) -> Vec<&str> {
        self.documents
            .iter()
            .filter(|document| document.comparison == Some(Comparison::Differs))
            .map(|document| document.id.as_str())
            .collect()
    }
}
